    public List<ThirdPartyProvider> testGetAll() throws Throwable {
    LOGGER.info( "ThirdPartyProviderTest:testGetAll() - Retrieving Collection of ThirdPartyProviders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ThirdPartyProvider : " );
    List<ThirdPartyProvider> collection  = null;

    try {
        // call the static get method on the ThirdPartyProviderService
        collection = service.getAllThirdPartyProvider();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ThirdPartyProvider currEntity  = null;
            Iterator<ThirdPartyProvider> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getThirdPartyProviderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

